const toJD = (iso) => { const [y, m, d] = iso.split('-').map(Number); return (Date.UTC(y, m - 1, d) / 86400000) + 2440587.5; };
/** All eclipses with maximum in [startISO, endISO] inclusive. */
export function eclipsesInRange(startISO, endISO) { const a = toJD(startISO), b = toJD(endISO) + 1; return ECLIPSES.filter((e) => e.jd >= a && e.jd <= b); }
/** The next eclipse on or after dateISO (null if beyond the table). */
export function nextEclipse(dateISO) { const j = toJD(dateISO); return ECLIPSES.find((e) => e.jd >= j) || null; }
